import * as baseline from './base/runtime.ts';
import * as cached from './cache/runtime.ts';
import * as linear from './linear/runtime.ts';
import { number_operator, standard_operators } from './base/operators.ts';
const variants = {baseline, cached, linear};
const symbols=['+','*','-','/','%','**','<','>'];
const words=['add','times','less','over','mod','power','below','above'];
const median=(x:number[])=>x.toSorted((a,b)=>a-b)[Math.floor(x.length/2)];
let sink:unknown;
const cases:{name:string;run:()=>unknown;count:number}[]=[];
const qualification:unknown[]=[];
for(const family of ['symbol','word'])for(const size of [1,2,4,8,16,100]){
 const registry:Record<string,ReturnType<typeof number_operator>>={};
 const tokens:string[]=[];
 for(let i=0;i<size;i++){let token=symbols[i];if(family==='word')token=words[i];if(i>=8)token='op'+i;tokens.push(token);registry[token]=number_operator(6,'left',(a,b)=>a+b);}
 for(const [name,runtime] of Object.entries(variants)){
  const grammar=runtime.make_grammar(registry,{},[]);
  const source='?0 '+tokens[0]+' (?1 '+tokens[size-1]+' 3) '+tokens[0]+' ?0';
  const probes=[tokens[0]+' 1',tokens[Math.floor(size/2)]+' 1',tokens[size-1]+' 1','?0','123','unknown','(',tokens[0]+'name'];
  const lookup=runtime.lookup_probe(grammar,probes);
  const plan=runtime.compile(grammar,source);
  const value=runtime.execute(plan,[4,5]);if(value!==16)throw new Error('bad workload '+source+' => '+value);
  cases.push({name:`${family}/${size}/${name}/lookup-twice`,run:lookup,count:100000});
  cases.push({name:`${family}/${size}/${name}/compile`,run:()=>runtime.compile(grammar,source),count:10000});
  cases.push({name:`${family}/${size}/${name}/construct-compile`,run:()=>runtime.compile(runtime.make_grammar(registry,{},[]),source),count:2000});
  qualification.push({family,size,name,value});
 }
}
for(const [name,runtime] of Object.entries(variants)){
 const grammar=runtime.make_grammar(standard_operators,{sum:(...xs:unknown[])=>xs.reduce<number>((a,b)=>a+Number(b),0)},[]);
 for(const source of ['?0 + ?1 * 3','sum 1 2 3 + ?0','(?0 + ?1) * (?0 - ?1) + (?0 * ?1)','1+-2','true && false','1 + (','1 &&& 2']){
  let result:unknown;try {const plan=runtime.compile(grammar,source);result=runtime.execute(plan,[4,5].slice(0,plan.argumentCount));}catch(e){const x=e as {code:string;span:unknown};result={code:x.code,span:x.span};}
  qualification.push({name,source,result});
  cases.push({name:`standard/${source}/${name}/compile`,run:()=>{try{return runtime.compile(grammar,source)}catch{return null}},count:10000});
 }
}
const samples:Record<string,number[]>={};
for(let round=0;round<5;round++){
 const order=[...cases];if(round%2===1)order.reverse();
 for(const {name,run,count} of order){for(let i=0;i<count/10;i++)sink=run();const start=performance.now();for(let i=0;i<count;i++)sink=run();(samples[name]??=[]).push((performance.now()-start)*1e6/count);}
}
const byCase=Object.fromEntries(Object.entries(samples).map(([name,x])=>[name,{median_ns:median(x),samples_ns:x}]));
console.log(JSON.stringify({version:Deno.version,pins:JSON.parse(await Deno.readTextFile(new URL('./pins.json',import.meta.url))),method:'five alternating-order wall-time samples after 10% warmup; lookup100k,compile10k,construct+compile2k calls; lookup constructs a fresh Parser and invokes arity2 twice per cursor',cases:byCase,qualification,sink:typeof sink},null,2));

